              {"cells": ["<b>Thải qua thận</b>", "<em>80%</em>", "66% (EHRA: 35%)", "<em>27%</em>", "50%"], "at": 1, "hl": "L1", "c": "coral"},
              {"cells": ["<b>Bán thải</b>", "12–17 giờ", "5–9 giờ", "12 giờ", "10–14 giờ"], "at": 2, "c": "teal"},
