              {"cells": ["<b>Dabigatran</b>", "150 mg × 2", "≥ 80 tuổi · verapamil · cân nhắc: 75–80 tuổi, CrCl 30–50, viêm dạ dày, trào ngược, nguy cơ chảy máu", "110 mg × 2"], "at": 1, "c": "blue"},
              {"cells": ["<b>Edoxaban</b>", "60 mg × 1", "CrCl 15–50 · ≤ 60 kg · ciclosporin, dronedarone, erythromycin, ketoconazole", "30 mg × 1"], "at": 2, "c": "amber"},
