SHORT = ["Nền tảng và đánh giá nguy cơ", "Chọn thuốc và liều", "Già yếu, thận, gan, chảy máu, van tim", "Mạch vành, đột quỵ, ung thư", "Thủ thuật, chảy máu và góc hồi sức"]

for n in range(1, 6):
    d = head(n, SHORT[n - 1])
    for sc in P[n]:
        if "ref" not in sc:
            sc["ref"] = ""
        if sc["layout"] == "bars" and sc.get("notes") and isinstance(sc["notes"][0], str):  # ghi chú cột phải: dạng {t, at, c}
            nl = len(sc["lines"]); cs = ["blue", "amber", "violet", "teal"]
            sc["notes"] = [{"t": t, "at": min(nl - 1, i + 1), "c": cs[i % 4]} for i, t in enumerate(sc["notes"])]
            sc.setdefault("notes_w", 560)
    d["scenes"] = P[n]
    out = os.path.join(ROOT, "projects", f"rung-nhi-phan-{n}")
    os.makedirs(out, exist_ok=True)
    with open(os.path.join(out, "script.json"), "w", encoding="utf8") as f:
        json.dump(d, f, ensure_ascii=False, indent=1)
    words = sum(len(" ".join(s["lines"]).split()) for s in P[n])
    print(f"Phần {n}: {len(P[n])} cảnh, {words} từ (~{words / 140:.1f} phút)")
